#include <errno.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "../../daqiri-vrt-prologue.h"
#include "test_framework.h"

struct dq_vrt_golden {
	const char *name;
	uint8_t type;
	bool has_class, has_trailer;
	uint8_t tsi, tsf, pkt_count;
	uint16_t size_words;
	uint32_t stream_id, oui;
	uint16_t info_class, packet_class;
	uint32_t tsi_secs;
	uint64_t tsf_frac;
	unsigned prologue_bytes, payload_bytes;
	bool valid;
};

#include "../resources/vrt/expected.h"

#define N_GOLDEN (sizeof(golden) / sizeof(golden[0]))

/* Returns a malloc'd buffer of exactly the file size (never zero-sized). */
static uint8_t *load(const char *name, size_t *len)
{
	char path[1024];
	uint8_t *buf;
	long sz;
	FILE *f;

	snprintf(path, sizeof(path), "%s/%s", TESTS_VRT_DIR, name);
	f = fopen(path, "rb");
	if (!f)
		return NULL;
	fseek(f, 0, SEEK_END);
	sz = ftell(f);
	fseek(f, 0, SEEK_SET);
	buf = malloc(sz ? sz : 1);
	if (buf && fread(buf, 1, sz, f) != (size_t)sz) {
		free(buf);
		buf = NULL;
	}
	fclose(f);
	*len = sz;
	return buf;
}

static void check(const struct dq_vrt_golden *g)
{
	struct dq_vrt_prologue p;
	size_t len = 0;
	uint8_t *buf = load(g->name, &len);
	int ret;

	TEST_ASSERT_PTR_NOT_NULL(buf, g->name);
	if (!buf) {
		fprintf(stderr, "cannot load %s\n", g->name);
		return;
	}

	/* Heap buffer sized exactly: ASan catches any over-read. */
	memset(&p, 0xAA, sizeof(p));
	ret = dq_vrt_parse(buf, len, &p);
	if (!g->valid) {
		TEST_ASSERT_EQ(ret, -EBADMSG, g->name);
		goto out;
	}
	TEST_ASSERT_EQ(ret, 0, g->name);
	if (ret)
		goto out;

	TEST_ASSERT_EQ(len, (size_t)g->size_words * 4, "file size");
	TEST_ASSERT_EQ(p.type, g->type, "type");
	TEST_ASSERT_EQ(p.has_sid, g->type == 1 || g->type >= 4, "has_sid");
	TEST_ASSERT_EQ(p.has_class, g->has_class, "has_class");
	TEST_ASSERT_EQ(p.has_trailer, g->has_trailer, "has_trailer");
	TEST_ASSERT_EQ(p.tsm, 0, "tsm");
	TEST_ASSERT_EQ(p.tsi, g->tsi, "tsi");
	TEST_ASSERT_EQ(p.tsf, g->tsf, "tsf");
	TEST_ASSERT_EQ(p.pkt_count, g->pkt_count, "pkt_count");
	TEST_ASSERT_EQ(p.size_words, g->size_words, "size_words");
	TEST_ASSERT_EQ(p.stream_id, g->stream_id, "stream_id");
	TEST_ASSERT_EQ(p.oui, g->oui, "oui");
	TEST_ASSERT_EQ(p.info_class, g->info_class, "info_class");
	TEST_ASSERT_EQ(p.packet_class, g->packet_class, "packet_class");
	TEST_ASSERT_EQ(p.tsi_secs, g->tsi_secs, "tsi_secs");
	TEST_ASSERT(p.tsf_frac == g->tsf_frac, "tsf_frac");
	TEST_ASSERT_EQ(p.prologue_bytes, g->prologue_bytes, "prologue_bytes");
	TEST_ASSERT_EQ(p.payload_bytes, g->payload_bytes, "payload_bytes");
out:
	free(buf);
}

TEST_FUNCTION(golden_vectors)
{
	size_t i;

	for (i = 0; i < N_GOLDEN; i++)
		check(&golden[i]);
}

TEST_FUNCTION(context_packet)
{
	struct dq_vrt_prologue p;
	size_t len;
	uint8_t *buf = load("context_cif0.bin", &len);

	TEST_ASSERT_PTR_NOT_NULL(buf, "load context_cif0.bin");
	if (!buf)
		return;
	TEST_ASSERT_EQ(dq_vrt_parse(buf, len, &p), 0, "parse context");
	TEST_ASSERT_EQ(p.type, DQ_VRT_IF_CONTEXT, "context type");
	TEST_ASSERT(p.has_sid, "context has_sid");
	free(buf);
}

TEST_FUNCTION(rejected_types)
{
	static const uint8_t types[] = { 2, 3, 6, 7 };
	struct dq_vrt_prologue p;
	/* Room for SID so only the type decides. Type 3 is rejected too. */
	uint8_t buf[8] = { 0 };
	size_t i;

	for (i = 0; i < sizeof(types); i++) {
		buf[0] = types[i] << 4;
		buf[3] = 2; /* size_words */
		TEST_ASSERT_EQ(dq_vrt_parse(buf, sizeof(buf), &p), -EBADMSG,
			       "unsupported type rejected");
	}
}

TEST_FUNCTION(size_checks)
{
	struct dq_vrt_prologue p;
	uint8_t buf[40] = { 0 };

	/* type 1, C=1, T=1, TSI=1, TSF=1: 7 prologue words + trailer. */
	buf[0] = 0x1C;
	buf[1] = 0x50;
	buf[3] = 7; /* no payload room once the trailer is counted */
	TEST_ASSERT_EQ(dq_vrt_parse(buf, sizeof(buf), &p), -EBADMSG,
		       "no room for trailer");
	buf[3] = 8;
	TEST_ASSERT_EQ(dq_vrt_parse(buf, sizeof(buf), &p), 0,
		       "empty payload plus trailer");
	TEST_ASSERT_EQ(p.payload_bytes, 0, "empty payload bytes");

	/* size_words * 4 > len */
	buf[3] = 11;
	TEST_ASSERT_EQ(dq_vrt_parse(buf, sizeof(buf), &p), -EBADMSG,
		       "size beyond buffer");
	/* len < 4 */
	TEST_ASSERT_EQ(dq_vrt_parse(buf, 3, &p), -EBADMSG, "len < 4");
	TEST_ASSERT_EQ(dq_vrt_parse(buf, 0, &p), -EBADMSG, "len 0");
}

int main(void)
{
	RUN_TEST(golden_vectors);
	RUN_TEST(context_packet);
	RUN_TEST(rejected_types);
	RUN_TEST(size_checks);
	TEST_SUMMARY();
}
